INSERT INTO `san_shop_faktura_statustyper` (`id`, `status_id`, `status_beskrivelse`, `status_actionnavn`, `status_forklaring`, `kunde_vis_navn`, `status_javascriptOnClick`, `usynlig`, `ordering`) VALUES
(1, 0, 'Ikke bekræftet', NULL, 'Indkomne ordrer får automatisk denne status.', 'Ikke bekræftet', 'javascript:opdater_ajax(\'header-sitemanager.php?p=ordre_aendre_status&amp;aendre_til=###statusid###&amp;ordreid=###ordreid###&amp;fakturaid=###fakturaid###\',\'Status for ordren er nu blevet opdateret.\');', 0, 50),
(2, 1, 'Ordrebekræftelse', NULL, 'Når ordren er under behandling / ved at blive pakket.', 'Bekræftet', NULL, 0, 60),
(3, 2, 'I restordre', NULL, 'Hvis der er varer i restordre.', 'I restordre', 'javascript:if(confirm(\'Skal systemet sende en e-mail til kunden vedr. at ordren er i restordre?\')){opdater_ajax(\'header-sitemanager.php?p=ordre_aendre_status&amp;aendre_til=###statusid###&amp;ordreid=###ordreid###&amp;fakturaid=###fakturaid###&amp;send_mail=restordre\',\'Status for ordren er nu blevet opdateret.<br><br>Kunden er blevet informeret om, at ordren er i restordre.\');}else{opdater_ajax(\'header-sitemanager.php?p=ordre_aendre_status&amp;aendre_til=###statusid###&amp;ordreid=###ordreid###&amp;fakturaid=###fakturaid###&amp;s\',\'Status for ordren er nu blevet opdateret.\');}', 0, 70),
(4, 10, 'Delleveret', 'Afhentet', 'Når varen er afhentet/delvist afhentet', 'Delleveret', 'javascript:TINY.box.show(\'header-sitemanager.php?p=track_and_trace_prompt&amp;aendre_til=###statusid###&amp;ordreid=###ordreid###&amp;fakturaid=###fakturaid###\',1,400,240,1);', 0, 90),
(5, 20, 'Annulleret', NULL, 'Slettede ordrer', 'Annulleret', 'javascript:if(confirm(\'Skal der sendes en mail til kunden med en besked om, at ordren er slettet?\')){opdater_ajax(\'header-sitemanager.php?p=ordre_aendre_status&amp;aendre_til=###statusid###&amp;ordreid=###ordreid###&amp;fakturaid=###fakturaid###&amp;send_mail=slettet\',\'Ordren er nu slettet og kan findes under Slettede ordrer.<br><br>Kunden er blevet orienteret pr. e-mail.\');}else{opdater_ajax(\'header-sitemanager.php?p=ordre_aendre_status&amp;aendre_til=###statusid###&amp;ordreid=###ordreid###&amp;fakturaid=###fakturaid###\',\'Ordren er nu slettet og kan findes under Slettede ordrer.\');}', 0, 110),
(6, 6, 'Klar til afhentning', NULL, 'Når ordren er klar til afhentning.', 'Klar til afhentning', NULL, 0, 80),
(7, 7, 'Delleveret', 'Leverance', 'Bruges når der skal sendes en pakke fra ordren. Kan indeholde dele af eller hele ordren.\r\nHvis det er hele ordren, så er der en hardcoded if-sætning der bytter status beskrivelses-teksten ud med \"Leveret\"', 'Delleveret', NULL, 0, 100);